  const sups=(P.supporters||[]).length?`<div class="an-tw"><table class="an-tb"><thead><tr><th>${esc(M3("Supporter","Supporter","Supporter"))}</th><th>${esc(M3("Badge","Badge","Selo"))}</th><th>${esc(M3("Founding offer","Oferta fundador","Oferta fundador"))}</th><th>${esc(M3("Given","Aportado","Doado"))}</th><th>${esc(M3("Payments","Pagos","Pagamentos"))}</th><th>${esc(M3("First, last","Primero, último","Primeiro, último"))}</th><th>${esc(M3("Account since","Cuenta desde","Conta desde"))}</th><th>${esc(M3("Last in the app","Última vez en la app","Última vez no app"))}</th></tr></thead><tbody>${P.supporters.map(x=>`<tr><td>${who(x.name,x.id,x.staff)}${x.pro?` <span class="pill acc">PRO</span>`:""}</td><td>${x.badge?`<span class="good">♥ ${esc(BS[x.badgeSrc]||x.badgeSrc)}</span>${x.hidden?` <small class="note">${esc(M3("hidden by them","oculto por él","oculto por ele"))}</small>`:""}`:`<span class="note">${esc(M3("none","no","não"))}</span>`}</td><td>${x.founder?`<span class="acc">${esc(M3("Yes","Sí","Sim"))}</span>${x.founderNoFloor?` <small class="note">${esc(M3(`under $${P.min}, kept from before`,`menos de $${P.min}, se mantiene de antes`,`menos de $${P.min}, mantida de antes`))}</small>`:""}`:`<span class="note">${esc(M3("No","No","Não"))}</span>`}</td><td class="mono"><b>${esc(mny(x.given))}</b></td><td class="mono">${admMNum(x.donations)}${x.refunded?` <small class="bad">${x.refunded} ${esc(M3("refunded","reemb.","reemb."))}</small>`:""}</td><td class="mono">${x.first?esc(dd(x.first))+(x.last!==x.first?" · "+esc(dd(x.last)):""):"–"}</td><td class="mono">${esc(dd(x.created))}</td><td class="mono">${x.seen?esc(admAgo(x.seen)):"–"}</td></tr>`).join("")}</tbody></table></div>`:admMNone();
