    +admMCard(M3("Donations","Donaciones","Doações"),M3("Drivers who saw the donation bar, pressed Donate or said no, each week, then the donations paid.","Pilotos que vieron la barra de donación, pulsaron Donar o dijeron que no, cada semana, y después las donaciones pagadas.","Pilotos que viram a barra de doação, tocaram em Doar ou disseram não, a cada semana, e depois as doações pagas."),
      tbl([[M3("Saw the bar","Vio la barra","Viu a barra"),"k:act:donate_bar_shown"],[M3("Pressed Donate on the bar","Pulsó Donar en la barra","Tocou em Doar na barra"),"k:act:donate_bar"],[M3("Said no","Dijo que no","Disse não"),"k:act:donate_bar_no"],[M3("Donate from the menu","Donar desde el menú","Doar pelo menu"),"k:act:donate_menu"],[M3("Support from the PRO window","Apoyar desde la ventana PRO","Apoiar pela janela PRO"),"k:act:donate_pro"],[M3("Donations paid","Donaciones pagadas","Doações pagas"),"donations"],...cur.map(k=>[M3("Raised","Recaudado","Arrecadado")+" "+k.slice(12).toUpperCase(),k,money(k.slice(12))]),[M3("Supporters","Supporters","Supporters"),"supporters"]]))
