function admDataHTML(h,r){const F=h.families||[],job=h.job,st={ok:["good",M3("arriving","llegando","chegando")],quiet:["bad",M3("stopped","parado","parou")],never:["",M3("never sent","nunca enviado","nunca enviado")]};
  const fam=`<div class="an-tw"><table class="an-tb"><thead><tr><th>${esc(M3("Counter","Contador","Contador"))}</th><th>${esc(M3("From","Desde","De"))}</th><th>${esc(M3("Last day","Último día","Último dia"))}</th><th>${esc(M3("Accounts in 7 days","Cuentas en 7 días","Contas em 7 dias"))}</th><th></th></tr></thead><tbody>${F.map(x=>`<tr><td><b>${esc(ADM_FAM[x.fam]?M3(...ADM_FAM[x.fam]):x.fam)}</b> <small class="note mono">${esc(x.fam)}:</small></td><td>${esc(admDevName(x.device))}</td><td class="mono">${esc(x.last||"–")}</td><td class="mono">${admMNum(x.users7)}</td><td><span class="${st[x.state][0]}">${esc(st[x.state][1])}</span>${x.state==="quiet"?` <small class="note">${x.ago} ${esc(M3("days","días","dias"))}</small>`:""}</td></tr>`).join("")}</tbody></table></div>`;
  const reads=(h.reads||[]).length?`<div class="an-tw"><table class="an-tb"><thead><tr><th>${esc(M3("Day","Día","Dia"))}</th><th>${esc(M3("Route","Ruta","Rota"))}</th><th>${esc(M3("Requests","Peticiones","Pedidos"))}</th><th>${esc(M3("Rows read","Filas leídas","Linhas lidas"))}</th><th>${esc(M3("Rows written","Filas escritas","Linhas escritas"))}</th></tr></thead><tbody>${h.reads.map(x=>`<tr><td class="mono">${esc(x.day)}</td><td class="mono">${esc(x.route)}</td><td class="mono">${admMNum(x.reqs)}</td><td class="mono">${admMNum(x.read)}</td><td class="mono">${admMNum(x.written)}</td></tr>`).join("")}</tbody></table></div>`:admMNone();
  const defs=[[M3("Week","Semana","Semana"),M3("Monday to Sunday, UTC.","De lunes a domingo, UTC.","De segunda a domingo, UTC.")],[M3("Used it","Lo usó","Usou"),M3("Opened a screen of any app that day.","Abrió una pantalla de alguna app ese día.","Abriu uma tela de algum app naquele dia.")],[M3("Drove, raced","Condujo, corrió","Dirigiu, correu"),M3("Uploaded a session that day, and one of them was a race.","Subió una sesión ese día, y una de ellas fue una carrera.","Enviou uma sessão naquele dia, e uma delas foi uma corrida.")],[M3("Weekly user","Usuario semanal","Usuário semanal"),M3("Used it or drove in the week. The agent running in the background is counted apart.","Lo usó o condujo en la semana. El agente en segundo plano se cuenta aparte.","Usou ou dirigiu na semana. O agente em segundo plano é contado à parte.")],[M3("Drivers","Pilotos","Pilotos"),M3("Every account except the admins and the testers.","Todas las cuentas menos los admins y los testers.","Todas as contas menos os admins e os testers.")],[M3("Still using it a week later","Sigue usándolo una semana después","Ainda usa uma semana depois"),M3("A new account active on any of days 7 to 13 after the day it was created.","Una cuenta nueva activa en alguno de los días 7 a 13 tras el día en que se creó.","Uma conta nova ativa em algum dos dias 7 a 13 depois do dia em que foi criada.")],[M3("Source","Origen","Origem"),M3("The account's first visit, its tagged link, or the installer download's source for accounts made in the agent.","La primera visita de la cuenta, su enlace etiquetado o el origen de la descarga del instalador para las cuentas creadas en el agente.","A primeira visita da conta, seu link marcado ou a origem do download do instalador para as contas criadas no agente.")]];
  return admMCard(M3("Is every counter arriving","Llegan todos los contadores","Todos os contadores estão chegando"),M3("Each kind of counter and the device it comes from, with the last day it sent anything in 30 days. Stopped means it sent before and nothing came for 3 days.","Cada tipo de contador y el dispositivo del que viene, con el último día que envió algo en 30 días. Parado significa que enviaba y lleva 3 días sin llegar nada.","Cada tipo de contador e o dispositivo de onde vem, com o último dia em que enviou algo em 30 dias. Parou significa que enviava e há 3 dias não chega nada."),fam+(h.since&&h.since.usage?`<p class="note">${esc(M3("App usage is counted since","El uso de las apps se cuenta desde","O uso dos apps é contado desde"))} ${esc(h.since.usage)}.</p>`:""))
    +admMCard(M3("The weekly numbers","Los números semanales","Os números semanais"),M3("The server adds the weeks up once a day at 03:00 UTC and writes only what changed. Add up now does the last 15 weeks, Add up everything goes back to the first day there is.","El servidor suma las semanas una vez al día a las 03:00 UTC y escribe solo lo que cambió. Sumar ahora hace las últimas 15 semanas, y Sumar todo vuelve al primer día que hay.","O servidor soma as semanas uma vez por dia às 03:00 UTC e grava só o que mudou. Somar agora faz as últimas 15 semanas, e Somar tudo volta ao primeiro dia que existe."),
      `<dl class="kv adm-kv"><dt>${esc(M3("Last run","Última vez","Última vez"))}</dt><dd>${job&&job.at?esc(admAgo(job.at))+` · ${admMNum(job.weeks)} ${esc(M3("weeks","semanas","semanas"))} · ${admMNum(job.read)} ${esc(M3("rows read","filas leídas","linhas lidas"))} · ${admMNum(job.wrote)} ${esc(M3("written","escritas","gravadas"))} · ${admMNum(job.ms)} ms`:esc(M3("never","nunca","nunca"))}</dd></dl><div class="frow" style="gap:8px;flex-wrap:wrap"><button type="button" class="btn small primary" data-mrun="0">${esc(M3("Add up now","Sumar ahora","Somar agora"))}</button><button type="button" class="btn small" data-mrun="1">${esc(M3("Add up everything","Sumar todo","Somar tudo"))}</button><button type="button" class="btn small" id="admMCsv">${esc(M3("Download the weeks as CSV","Descargar las semanas en CSV","Baixar as semanas em CSV"))}</button></div>`)
    +admMCard(M3("What it costs","Lo que cuesta","O que custa"),M3("The database rows the Analytics and the daily job read and wrote in the last 7 days.","Las filas de la base de datos que las analíticas y la tarea diaria leyeron y escribieron en los últimos 7 días.","As linhas do banco de dados que as análises e a tarefa diária leram e gravaram nos últimos 7 dias."),reads)
    +admMCard(M3("What each word means","Lo que significa cada palabra","O que cada palavra significa"),"",`<dl class="kv adm-kv">${defs.map(([a,b])=>`<dt>${esc(a)}</dt><dd>${esc(b)}</dd>`).join("")}</dl>`)}
function admMetricsCsv(r){const W=r.weeks||[],q=s=>'"'+String(s).replace(/"/g,'""')+'"',lines=[["number",...W].map(q).join(",")];for(const k of Object.keys(r.series||{}).sort())lines.push([q(k),...r.series[k]].join(","));
  const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([lines.join("\n")],{type:"text/csv"}));a.download="pitlanehq-weeks.csv";document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
/* one tab of the Analytics section (kind m_<tab>), drawn into the admin page's body; reload asks the server again */
async function admMetrics(kind,body,reload){const get=()=>cloudGet(`/community/admin/metrics?weeks=${ADM.mw||12}&aud=${ADM.maud||0}`);
  const top=()=>{body.querySelectorAll("[data-mw]").forEach(b=>b.onclick=()=>{ADM.mw=+b.dataset.mw;reload()});body.querySelectorAll("[data-maud]").forEach(b=>b.onclick=()=>{ADM.maud=+b.dataset.maud;reload()})};
  if(kind==="m_data"){const [h,r]=await Promise.all([cloudGet("/community/admin/metrics/health"),get()]);body.innerHTML=admDataHTML(h,r);
    body.querySelectorAll("[data-mrun]").forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent=M3("Adding up…","Sumando…","Somando…");try{const o=await cloudPost("/community/admin/metrics/run",{all:b.dataset.mrun==="1"});toast(M3(`Done. ${o.weeks} weeks, ${o.wrote} rows written.`,`Hecho. ${o.weeks} semanas, ${o.wrote} filas escritas.`,`Feito. ${o.weeks} semanas, ${o.wrote} linhas gravadas.`));reload()}catch(e){toast(e.message);b.disabled=false}});
    const c=body.querySelector("#admMCsv");if(c)c.onclick=()=>admMetricsCsv(r);return}
  const r=await get();
  if(kind==="m_monday"){body.innerHTML=admMondayHTML(r);top();const f=body.querySelector("#admMT");if(f)f.onsubmit=async ev=>{ev.preventDefault();const t={};f.querySelectorAll("[data-mt]").forEach(i=>{(t[i.dataset.mt]||(t[i.dataset.mt]=[null,null]))[+i.dataset.mi]=i.value===""?null:Number(i.value)});
      try{await cloudPost("/community/admin/metrics/targets",{d1:f.querySelector("#admMT1").value,d2:f.querySelector("#admMT2").value,t});toast(M3("Targets saved","Objetivos guardados","Metas salvas"));reload()}catch(e){toast(e.message)}};return}
  if(kind==="m_growth"){body.innerHTML=admGrowthHTML(r);top();const f=body.querySelector("#admLk");
    if(f)f.onsubmit=async ev=>{ev.preventDefault();try{const o=await cloudPost("/community/admin/links",{name:body.querySelector("#admLkN").value,place:body.querySelector("#admLkP").value});try{await navigator.clipboard.writeText("https://pitlanehq.app/?ref="+o.tag)}catch(e){}toast(M3("Link made and copied","Enlace creado y copiado","Link criado e copiado"));reload()}catch(e){toast(e.message)}};
    body.querySelectorAll("[data-lkc]").forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.lkc);toast(M3("Link copied","Enlace copiado","Link copiado"))}catch(e){}});
    body.querySelectorAll("[data-lkd]").forEach(b=>b.onclick=async()=>{if(!(await uiConfirm(M3("Remove this link from the list? Its visits and accounts stay counted under its tag.","¿Quitar este enlace de la lista? Sus visitas y cuentas siguen contadas con su etiqueta.","Remover este link da lista? As visitas e contas dele continuam contadas com a marca."))))return;try{await cloudDel("/community/admin/links/"+encodeURIComponent(b.dataset.lkd));reload()}catch(e){toast(e.message)}});return}
  if(kind==="m_activation"){body.innerHTML=admActivationHTML(r);top();return}
  if(kind==="m_sales"){const P=await cloudGet("/community/admin/metrics/payments").catch(()=>null);body.innerHTML=admSalesHTML(r,P);top();
    body.querySelectorAll("[data-thx]").forEach(b=>b.onclick=async()=>{const e=String(await uiPrompt(M3("The donor's email (the one they paid with or their account's)","El email del donante (con el que pagó o el de su cuenta)","O email do doador (o do pagamento ou da conta)"),"")||"").trim();if(!e)return;b.disabled=true;try{await cloudPost("/community/admin/metrics/payments/thanks",{id:b.dataset.thx,email:e});toast(M3("Thank-you sent","Agradecimiento enviado","Agradecimento enviado"));b.textContent="✓"}catch(err){toast(err.message);b.disabled=false}});return}
  const draw=()=>{body.innerHTML=admRetentionHTML(r);top();body.querySelectorAll("[data-mmeas]").forEach(b=>b.onclick=()=>{ADM.mmeas=b.dataset.mmeas;draw()});const s=body.querySelector("#admMSplit");if(s)s.onchange=()=>{ADM.msplit=s.value;draw()}};
  if(!(r.cohorts||[]).some(c=>c.split===(ADM.msplit||"")))ADM.msplit="";draw()}
/* the Telemetry panels and modes the drivers show (the Summary's analytics; counted once a day each, so days) */
function admLiveHTML(L,card,num){const T=Tx,P=L.filter(x=>!x.w.startsWith("mode.")),Mo=L.filter(x=>x.w.startsWith("mode.")),mx=Math.max(1,...P.map(x=>x.users)),nm=w=>{try{const n=lyaName(w);if(n&&n!=="w."+w)return n}catch(e){}return w},mn={basic:M3("Basic","Básico","Básico"),full:M3("Full","Completo","Completo"),cmp:M3("Lap compare","Comparar vueltas","Comparar voltas")};
  return card(M3("Telemetry panels","Paneles de Telemetría","Painéis da Telemetria"),M3("The panels drivers keep on the Telemetry screen and the mode they use, counted once a day after twenty seconds on it.","Los paneles que los pilotos tienen en la pantalla de Telemetría y el modo que usan, contados una vez al día tras veinte segundos en ella.","Os painéis que os pilotos mantêm na tela de Telemetria e o modo que usam, contados uma vez por dia depois de vinte segundos nela."),
    L.length?(Mo.length?`<p class="an-line">${Mo.map(x=>`${esc(mn[x.w.slice(5)]||x.w.slice(5))} <b>${num(x.users)}</b>`).join(" · ")}</p>`:"")+P.map(x=>`<div class="an-row"><span class="an-l">${esc(nm(x.w))}</span><span class="an-t"><i style="width:${(x.users/mx*100).toFixed(1)}%"></i></span><span class="an-v">${num(x.users)} <small>${num(x.days)} ${esc(M3("days","días","dias"))}</small></span></div>`).join(""):`<p class="note">${esc(T("Nothing counted yet.","Aún no se ha contado nada.","Nothing counted yet.","Nada contado ainda."))}</p>`)}
/* one account's steps with their days, under its detail (metrics.js) */
async function admStepsInto(box,id){try{const r=await cloudGet("/community/admin/metrics/account?id="+encodeURIComponent(id));if(!box.isConnected)return;
  box.innerHTML=`<div class="adm-grp">${esc(M3("Its steps","Sus pasos","Seus passos"))}</div><p class="note" style="margin:0 0 6px">${esc(M3("Came from","Vino de","Veio de"))} ${esc(admSrcName(r.src))}${r.page?" · "+esc(admPage(r.page)):""}${r.country?" · "+esc(admCountry(r.country)):""}</p><dl class="kv adm-kv">${(r.steps||[]).map(s=>`<dt>${esc(admStep(s.k))}</dt><dd class="mono">${esc(s.day)}</dd>`).join("")}</dl>`}catch(e){}}
